    // Heatmap cell dimensions
    // ══════════════════════════════════════════════════════════════════════

    /// Heatmap cell width = panel.w / n_x, cell height = panel.h / n_y.
    /// With 3 x-categories and 2 y-categories in a 300x200 panel:
    /// cell_w = 100, cell_h = 100.
    /// Targets rect.rs build_heatmap lines 343-344.
    #[test]
    fn bug_hunt_r2_heatmap_cell_dimensions() {
        let panel_w = 300.0_f64;
        let panel_h = 200.0_f64;
        let n_x = 3_usize;
        let n_y = 2_usize;

        let cell_w = panel_w / n_x as f64;
        let cell_h = panel_h / n_y as f64;

        assert!((cell_w - 100.0).abs() < 1e-9, "cell_w should be 100, got {cell_w}");
        assert!((cell_h - 100.0).abs() < 1e-9, "cell_h should be 100, got {cell_h}");
        assert!(cell_w > 0.0);
        assert!(cell_h > 0.0);
    }

    /// Single-cell heatmap (1x1): cell fills entire panel.
    #[test]
    fn bug_hunt_r2_heatmap_single_cell_fills_panel() {
        let panel_w = 300.0_f64;
        let panel_h = 200.0_f64;
        let n_x = 1_usize.max(1);
        let n_y = 1_usize.max(1);

        let cell_w = panel_w / n_x as f64;
        let cell_h = panel_h / n_y as f64;

        assert!((cell_w - 300.0).abs() < 1e-9);
        assert!((cell_h - 200.0).abs() < 1e-9);
    }

