    // Scene node serde: Polygon variant
    // ══════════════════════════════════════════════════════════════════════

    /// Polygon SceneNode with 2 rings (exterior + hole) must round-trip via JSON.
    #[test]
    fn bug_hunt_r2_polygon_serde_with_hole() {
        let node = SceneNode::Polygon {
            rings: vec![
                vec![[0.0, 0.0], [100.0, 0.0], [100.0, 100.0], [0.0, 100.0]],
                vec![[25.0, 25.0], [75.0, 25.0], [75.0, 75.0], [25.0, 75.0]],
            ],
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Polygon { rings, .. } = &back {
            assert_eq!(rings.len(), 2, "expected 2 rings (exterior + hole)");
            assert_eq!(rings[0].len(), 4, "exterior ring should have 4 vertices");
            assert_eq!(rings[1].len(), 4, "hole ring should have 4 vertices");
        } else {
            panic!("expected Polygon after round-trip");
        }
    }

    /// Empty polygon rings should serialize/deserialize without panicking.
    #[test]
    fn bug_hunt_r2_polygon_empty_rings_serde() {
        let node = SceneNode::Polygon {
            rings: vec![],
            style: default_fill_stroke(),
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Polygon { rings, .. } = &back {
            assert!(rings.is_empty());
        } else {
            panic!("expected Polygon after round-trip");
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Scene node serde: Image variant
    // ══════════════════════════════════════════════════════════════════════

    /// Image SceneNode with Url data should round-trip.
    #[test]
    fn bug_hunt_r2_image_url_serde() {
        let node = SceneNode::Image {
            x: 10.0,
            y: 20.0,
            w: 100.0,
            h: 50.0,
            data: ImageData::Url {
                url: "data:image/png;base64,iVBORw0KGgo=".to_string(),
            },
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Image { x, y, w, h, data } = &back {
            assert!((x - 10.0).abs() < 1e-9);
            assert!((y - 20.0).abs() < 1e-9);
            assert!((w - 100.0).abs() < 1e-9);
            assert!((h - 50.0).abs() < 1e-9);
            assert!(matches!(data, ImageData::Url { .. }));
        } else {
            panic!("expected Image after round-trip");
        }
    }

    /// Image SceneNode with Inline PNG data should round-trip.
    #[test]
    fn bug_hunt_r2_image_inline_serde() {
        let node = SceneNode::Image {
            x: 0.0,
            y: 0.0,
            w: 200.0,
            h: 200.0,
            data: ImageData::Inline {
                bytes: vec![137, 80, 78, 71, 13, 10, 26, 10], // PNG magic
                mime: ImageMime::Png,
            },
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Image { data, .. } = &back {
            if let ImageData::Inline { bytes, mime } = data {
                assert_eq!(bytes[0..4], [137, 80, 78, 71], "PNG magic header preserved");
                assert!(matches!(mime, ImageMime::Png));
            } else {
                panic!("expected ImageData::Inline after round-trip");
            }
        } else {
            panic!("expected Image after round-trip");
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Text mark limit boundary condition
    // ══════════════════════════════════════════════════════════════════════

    /// When limit equals the string length, no truncation should occur.
    /// Targets text.rs lines 161-169 where `raw_label.chars().count() > limit`.
    #[test]
    fn bug_hunt_r2_text_limit_equals_length_no_truncation() {
        let label = "Hello";
        let limit = 5_usize;
        let result = if limit > 0 && label.chars().count() > limit {
            let truncated: String = label.chars().take(limit.saturating_sub(1)).collect();
            format!("{truncated}\u{2026}")
        } else {
            label.to_string()
        };
        assert_eq!(result, "Hello", "limit == length should NOT truncate");
    }

    /// When limit is 1, the result should be just the ellipsis character.
    /// Targets text.rs line 163: `limit.saturating_sub(1)` = 0 chars before ellipsis.
    #[test]
    fn bug_hunt_r2_text_limit_one_is_just_ellipsis() {
        let label = "Hello";
        let limit = 1_usize;
        let result = if limit > 0 && label.chars().count() > limit {
            let truncated: String = label.chars().take(limit.saturating_sub(1)).collect();
            format!("{truncated}\u{2026}")
        } else {
            label.to_string()
        };
        assert_eq!(result, "\u{2026}", "limit=1 should produce just ellipsis");
    }

    /// When limit is 0, no truncation should occur (the condition `limit > 0` is false).
    /// Targets text.rs line 162: `if let Some(limit) = ... { if limit > 0 && ...`.
    #[test]
    fn bug_hunt_r2_text_limit_zero_no_truncation() {
        let label = "Hello";
        let limit = 0_usize;
        let result = if limit > 0 && label.chars().count() > limit {
            let truncated: String = label.chars().take(limit.saturating_sub(1)).collect();
            format!("{truncated}\u{2026}")
        } else {
            label.to_string()
        };
        assert_eq!(result, "Hello", "limit=0 should NOT truncate");
    }

