    /// VLine shape at (50, 50) with r=1e6: the arm and stroke_width must be finite.
    /// Targets point.rs emit_shape_nodes VLine branch (line 155-167).
    #[test]
    fn bug_hunt_r2_vline_huge_radius_finite() {
        let _cx = 50.0_f64;
        let cy = 50.0_f64;
        let r = 1e6_f64;
        let arm = r * 0.7;
        let sw = r * 0.35;
        assert!(arm.is_finite(), "arm must be finite");
        assert!(sw.is_finite(), "stroke_width must be finite");
        assert!((cy - arm).is_finite(), "y1 must be finite");
        assert!((cy + arm).is_finite(), "y2 must be finite");
    }

    /// HLine shape with r=0: zero-length line, both endpoints at center.
    /// Targets point.rs emit_shape_nodes HLine branch (line 168-180).
    #[test]
    fn bug_hunt_r2_hline_zero_radius() {
        let cx = 50.0_f64;
        let _cy = 50.0_f64;
        let r = 0.0_f64;
        let arm = r * 0.7;
        assert_eq!(arm, 0.0);
        assert_eq!(cx - arm, cx);
        assert_eq!(cx + arm, cx);
    }

